from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')

# Remove the old decorative text and add the compact categories control in its place.
old_header='''      </nav>\n      <div class="mc-text">Lil croak was here!</div>\n    </div>'''
new_header='''      </nav>\n      <button class="category-toggle" id="categoryToggle" type="button" aria-label="Open game categories" aria-controls="categorySidebar" aria-expanded="false">\n        <span class="category-toggle-icon" aria-hidden="true">☰</span>\n        <span class="category-toggle-label">Categories</span>\n      </button>\n    </div>'''
if old_header not in s:
    raise SystemExit('expected header marker not found')
s=s.replace(old_header,new_header,1)

bodyneedle='  <main class="page-wrap">'
if 'id="categorySidebar"' not in s:
    sidebar='''  <div class="category-overlay" id="categoryOverlay" hidden></div>\n  <aside class="category-sidebar" id="categorySidebar" aria-label="Game categories" aria-hidden="true">\n    <div class="category-sidebar-header">\n      <div>\n        <div class="category-kicker">Browse</div>\n        <h2>Game Categories</h2>\n      </div>\n      <button class="category-close" id="categoryClose" type="button" aria-label="Close categories">×</button>\n    </div>\n    <div class="category-list" id="categoryList"></div>\n  </aside>\n\n'''
    s=s.replace(bodyneedle,sidebar+bodyneedle,1)

css='''\n    .category-toggle{height:38px;display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:0 12px;border:1px solid rgba(255,255,255,.42);border-radius:11px;background:#0849b6;color:#fff;font-size:13px;font-weight:800;cursor:pointer;white-space:nowrap;box-shadow:0 5px 14px rgba(0,30,100,.20),inset 0 1px 0 rgba(255,255,255,.18);transition:transform .16s ease,background .16s ease,box-shadow .16s ease}\n    .category-toggle:hover{transform:translateY(-2px) scale(1.035);background:#063f9f;box-shadow:0 9px 21px rgba(0,30,100,.28),inset 0 1px 0 rgba(255,255,255,.26)}\n    .category-toggle:active{transform:translateY(1px) scale(.98)}\n    .category-toggle-icon{font-size:15px;line-height:1}\n    .category-overlay{position:fixed;inset:0;background:rgba(1,9,28,.48);backdrop-filter:blur(2px);z-index:1090;opacity:0;transition:opacity .2s ease}\n    .category-overlay.is-open{opacity:1}\n    .category-sidebar{position:fixed;top:0;right:0;height:100vh;width:min(350px,88vw);background:linear-gradient(180deg,#061734 0%,#0b2350 100%);color:#fff;z-index:1100;box-shadow:-18px 0 42px rgba(0,10,35,.35);transform:translateX(102%);transition:transform .24s cubic-bezier(.2,.8,.2,1);display:flex;flex-direction:column}\n    .category-sidebar.is-open{transform:none}\n    .category-sidebar-header{padding:24px 20px 16px;display:flex;align-items:flex-start;justify-content:space-between;gap:14px;border-bottom:1px solid rgba(255,255,255,.1)}\n    .category-kicker{font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:rgba(255,255,255,.55);font-weight:800;margin-bottom:4px}\n    .category-sidebar-header h2{margin:0;font-size:22px;line-height:1.2;font-weight:850}\n    .category-close{width:34px;height:34px;border:1px solid rgba(255,255,255,.2);border-radius:10px;background:rgba(255,255,255,.06);color:#fff;font-size:25px;line-height:1;cursor:pointer;transition:background .15s ease,transform .15s ease}\n    .category-close:hover{background:rgba(255,255,255,.12);transform:scale(1.05)}\n    .category-list{padding:14px 12px 20px;overflow:auto}\n    .category-item{width:100%;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 13px;margin:4px 0;border:1px solid transparent;border-radius:12px;background:transparent;color:#fff;text-align:left;cursor:pointer;transition:background .15s ease,border-color .15s ease,transform .15s ease}\n    .category-item:hover{background:rgba(255,255,255,.09);border-color:rgba(255,255,255,.09);transform:translateX(-2px)}\n    .category-item.is-active{background:rgba(37,115,255,.24);border-color:rgba(76,146,255,.34)}\n    .category-item-main{display:flex;align-items:center;gap:10px;min-width:0}\n    .category-dot{width:9px;height:9px;border-radius:50%;background:#4d91ff;box-shadow:0 0 0 4px rgba(77,145,255,.12);flex:0 0 auto}\n    .category-name{font-size:14px;font-weight:780;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n    .category-count{min-width:30px;height:24px;padding:0 8px;border-radius:999px;background:rgba(255,255,255,.1);color:rgba(255,255,255,.76);display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:800}\n    body.category-locked{overflow:hidden}\n    @media(max-width:830px){.category-toggle-label{display:none}.category-toggle{width:42px;padding:0}.header-actions{margin-left:auto}}\n    @media(max-width:570px){.category-toggle{width:100%;height:38px}.header-actions{margin-left:0}}\n'''
if '.category-toggle{' not in s:
    s=s.replace('</style>',css+'</style>',1)

js='''\n  /* Automatic game categories */\n  (function(){\n    const toggle=document.getElementById('categoryToggle');\n    const close=document.getElementById('categoryClose');\n    const sidebar=document.getElementById('categorySidebar');\n    const overlay=document.getElementById('categoryOverlay');\n    const list=document.getElementById('categoryList');\n    const grid=document.getElementById('gameGrid');\n    if(!toggle||!close||!sidebar||!overlay||!list||!grid)return;\n\n    const CATEGORY_RULES=[\n      ['Action',['action','shooter','combat','battle','fight','war','zombie','ninja','stickman','assassin','gun','sniper','strike','rush']],\n      ['Adventure',['adventure','quest','platform','dungeon','maze','escape','explore','survival','island','parkour']],\n      ['Arcade',['arcade','flappy','runner','run','jump','brick','ball','bubble','match','pinball','snake']],\n      ['Puzzle',['puzzle','logic','sudoku','2048','mahjong','word','memory','connect','block','brain','sort','merge']],\n      ['Racing',['racing','race','drift','car','cars','motor','bike','bmx','kart','traffic','drive']],\n      ['Sports',['football','soccer','basketball','baseball','golf','tennis','hockey','volleyball','bowling','pool','sports','skate','ski']],\n      ['Strategy',['strategy','tower','defense','defence','battle','td','idle','tycoon','manager','kingdom','chess','checkers']],\n      ['Simulation',['simulator','simulation','farming','farm','restaurant','cooking','shop','business','city','hotel','airport','life','house']],\n      ['Multiplayer',['multiplayer','2 player','2p','io','agar','slither','online']],\n      ['Casual',['clicker','idle','dress','makeup','color','drawing','quiz','trivia','fun','cute']]\n    ];\n    const categories=['All Games',...CATEGORY_RULES.map(x=>x[0])];\n    let active='All Games';\n    const normalize=s=>(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();\n    function games(){return Array.from(grid.querySelectorAll(':scope > .game-card')).map(card=>({card,title:(card.querySelector('h3')?.textContent||card.querySelector('img')?.alt||'Game').trim()}));}\n    function categoryFor(title){\n      const text=' '+normalize(title)+' ';\n      const scores=CATEGORY_RULES.map(([name,words])=>[name,words.reduce((n,w)=>n+(text.includes(' '+normalize(w)+' ')?1:0),0)]);\n      const best=scores.sort((a,b)=>b[1]-a[1])[0];\n      return best&&best[1]>0?best[0]:'Casual';\n    }\n    function openSidebar(){sidebar.classList.add('is-open');overlay.hidden=false;requestAnimationFrame(()=>overlay.classList.add('is-open'));sidebar.setAttribute('aria-hidden','false');toggle.setAttribute('aria-expanded','true');document.body.classList.add('category-locked');render();}\n    function closeSidebar(){sidebar.classList.remove('is-open');overlay.classList.remove('is-open');sidebar.setAttribute('aria-hidden','true');toggle.setAttribute('aria-expanded','false');document.body.classList.remove('category-locked');setTimeout(()=>{if(!sidebar.classList.contains('is-open'))overlay.hidden=true;},220);}\n    function render(){\n      const gs=games();\n      const counts=Object.fromEntries(categories.map(c=>[c,0]));\n      gs.forEach(g=>counts[categoryFor(g.title)]++);\n      list.innerHTML='';\n      categories.forEach(c=>{\n        const btn=document.createElement('button');btn.type='button';btn.className='category-item'+(active===c?' is-active':'');\n        btn.innerHTML='<span class="category-item-main"><span class="category-dot" aria-hidden="true"></span><span class="category-name"></span></span><span class="category-count"></span>';\n        btn.querySelector('.category-name').textContent=c;btn.querySelector('.category-count').textContent=String(c==='All Games'?gs.length:counts[c]);\n        btn.addEventListener('click',()=>{active=c;gs.forEach(g=>{const match=c==='All Games'||categoryFor(g.title)===c;g.card.style.display=match?'':'none';});list.querySelectorAll('.category-item').forEach(x=>x.classList.remove('is-active'));btn.classList.add('is-active');});\n        list.appendChild(btn);\n      });\n    }\n    toggle.addEventListener('click',()=>sidebar.classList.contains('is-open')?closeSidebar():openSidebar());\n    close.addEventListener('click',closeSidebar);overlay.addEventListener('click',closeSidebar);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sidebar.classList.contains('is-open'))closeSidebar();});\n    new MutationObserver(()=>render()).observe(grid,{childList:true});\n    render();\n  })();\n'''
if '/* Automatic game categories */' not in s:
    s=s.replace('  /* Personalized recommendation carousel */',js+'\n  /* Personalized recommendation carousel */',1)

p.write_text(s,encoding='utf-8')
